      "note": "AM_Angel_DeathSettle.validation.json#result = pass; AM_Angel_DeathSettle.validation.json#clip_sha256 = 26b8d28a609011facb6a57d2ee143cb32c1ec8a0ce804f13c5d3db02380ad287",
